function motionPointerInit(t){const e="motionPointer--hover";let o=document.createElement("div");o.classList.add("motionPointer"),document.querySelector("body").appendChild(o);const n=document.querySelector(".motionPointer");let i=n.offsetWidth,r=n.offsetHeight;if(n.style.left=-(i-6)/2+"px",n.style.top=-(r-6)/2+"px",t){let o=[];t.forEach((t=>{let e=document.querySelectorAll(t);return o.push(e),o})),o.forEach((t=>{t.forEach((t=>{t.addEventListener("mouseenter",(function(){n.classList.add(e),n.animate({width:[`${i}px`,2*i+"px"],height:[`${r}px`,2*r+"px"],left:[-(i-6)/2+"px",-(2*i-6)/2+"px"],top:[-(r-6)/2+"px",-(2*r-6)/2+"px"]},{duration:200,fill:"forwards"})})),t.addEventListener("mouseleave",(function(){n.classList.remove(e),n.animate({width:[2*i+"px",`${i}px`],height:[2*r+"px",`${r}px`],left:[-(2*i-6)/2+"px",-(i-6)/2+"px"],top:[-(2*r-6)/2+"px",-(r-6)/2+"px"]},{duration:200,fill:"forwards"})}))}))}))}document.addEventListener("mousemove",(function(t){let e=t.clientX,o=t.clientY;n.style.transform=`translate(${e}px, ${o}px)`}))}
